#!/usr/bin/env bash
# Usage: install-cargo-about.sh [dest-dir]
#
# Installs the pinned cargo-about release (scripts/pins/cargo-about.sh) into
# dest-dir, default $RUNNER_TEMP/cargo-about, after verifying its SHA-256, so
# third-party license listings are generated by the same, publicly visible
# tool version. Under GitHub Actions it exports CARGO_ABOUT and sets the step
# outputs path and version.
#
# Environment, for tests: CARGO_ABOUT_PLATFORM overrides the detected
# <os>-<arch>; CARGO_ABOUT_BASE_URL replaces the download location (the
# pinned SHA-256 still applies).
#
# Exit status: 1 when the download or the installed binary fails a check, 2 on
# usage errors. Kept compatible with the bash 3.2 shipped with macOS.
set -euo pipefail

SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
# shellcheck source=scripts/lib/common.sh
source "${SCRIPT_DIR}/lib/common.sh"
# shellcheck source=scripts/lib/fetch-pinned.sh
source "${SCRIPT_DIR}/lib/fetch-pinned.sh"
# shellcheck source=scripts/pins/cargo-about.sh
source "${SCRIPT_DIR}/pins/cargo-about.sh"

dest=${1:-${RUNNER_TEMP:+${RUNNER_TEMP}/cargo-about}}
[[ -n "${dest}" ]] || usage_error "usage: $0 <dest-dir> (or set RUNNER_TEMP)"
platform=${CARGO_ABOUT_PLATFORM:-$(host_platform)}
base_url=${CARGO_ABOUT_BASE_URL:-${CARGO_ABOUT_RELEASE_URL}}

cargo_about_release "${platform}" || usage_error "no pinned cargo-about for platform ${platform}"
stage=cargo-about-${CARGO_ABOUT_VERSION}-${cargo_about_target}
asset=${stage}.tar.gz

work=$(mktemp -d)
trap 'rm -rf "${work}"' EXIT

fetch_pinned "${base_url}/${asset}" "${cargo_about_sha256}" "${work}/${asset}"
tar -C "${work}" -xzf "${work}/${asset}"
dest=$(make_absolute_dir "${dest}")
cp "${work}/${stage}/cargo-about" "${dest}/cargo-about"
expect_version_output "${dest}/cargo-about" "cargo-about ${CARGO_ABOUT_VERSION}"
hand_over CARGO_ABOUT "${dest}/cargo-about" "${CARGO_ABOUT_VERSION}"
